const rows = items.map(i => i.json);

let totalSales = 0;
let ordersCount = 0;
const productCounts = {};
const orders = [];

for (const r of rows) {
  const rev = parseFloat((r.Total || r.Revenue || r.Amount || 0).toString().replace(/,/g,''));
  totalSales += isNaN(rev) ? 0 : rev;
  ordersCount += 1;

  const product = (r.Product || r.product || 'Unknown').toString();
  const qty = parseInt(r.Quantity || r.quantity || 1);
  productCounts[product] = (productCounts[product] || 0) + (isNaN(qty) ? 1 : qty);

  orders.push({
    orderId: r['Order ID'] || '',
    customer: r['Customer Name'] || '',
    product,
    quantity: qty,
    price: parseFloat(r.Price || 0),
    total: rev,
    date: r.Date || r.date || ''
  });
}

// find top product
let topProduct = null;
let topCount = 0;
for (const p of Object.keys(productCounts)) {
  if (productCounts[p] > topCount) {
    topCount = productCounts[p];
    topProduct = p;
  }
}

// structured final output
return [{
  json: {
    totalSales: Number(totalSales.toFixed(2)),
    ordersCount,
    topProduct,
    topProductUnits: topCount,
    products: productCounts,
    orders
  }
}];

