const m = items[0].json;
const labels = ['Sales ($)', 'Leads', 'Complaints'];
const values = [m.totalSales || 0, m.leadCount || 0, m.complaintCount || 0];

const chartConfig = {
  type: 'bar',
  data: {
    labels,
    datasets: [{ label: 'Daily snapshot', data: values }]
  },
  options: {
    title: { display: true, text: `Snapshot - ${m.date}` }
  }
};

const url = 'https://quickchart.io/chart?c=' + encodeURIComponent(JSON.stringify(chartConfig));
return [{ json: { ...m, chartUrl: url } }];
